import java.io.InputStream;import java.sql.Date;import java.util.*;import net.sf.jasperreports.engine.*;import net.sf.jasperreports.engine.data.JRMapCollectionDataSource;
public class VerificaReporteVacio {public static void main(String[] args)throws Exception{try(InputStream in=VerificaReporteVacio.class.getResourceAsStream("/restaurante/reportes/ventas.jrxml")){JasperReport r=JasperCompileManager.compileReport(in);Map<String,Object> p=new HashMap<>();p.put("DESDE",Date.valueOf("2026-01-01"));p.put("HASTA",Date.valueOf("2026-01-31"));JasperPrint j=JasperFillManager.fillReport(r,p,new JRMapCollectionDataSource(Collections.emptyList()));if(j.getPages().isEmpty())throw new AssertionError("Falta página sin datos");System.out.println("OK: reporte sin ventas conserva página informativa");}}}
